import { defineComponent, ref } from 'vue';

export default defineComponent({
  name: 'MultiStepForm',
  setup() {
    const currentStep = ref(1);
    const formData = ref({});

    const nextStep = () => {
      if (currentStep.value < 3) {
        currentStep.value++;
      }
    };

    const prevStep = () => {
      if (currentStep.value > 1) {
        currentStep.value--;
      }
    };

    return {
      currentStep,
      formData,
      nextStep,
      prevStep
    };
  },
  template: `
    <div>
      <div class="step-indicator">
        <span :class="{ active: currentStep === 1 }">Step 1</span>
        <span :class="{ active: currentStep === 2 }">Step 2</span>
        <span :class="{ active: currentStep === 3 }">Step 3</span>
      </div>

      <div v-if="currentStep === 1">
        <h2>Personal Information</h2>
        <input v-model="formData.name" placeholder="Name" />
        <input v-model="formData.email" placeholder="Email" />
      </div>

      <div v-if="currentStep === 2">
        <h2>Address Details</h2>
        <input v-model="formData.address" placeholder="Address" />
        <input v-model="formData.city" placeholder="City" />
      </div>

      <!-- Add navigation buttons here -->
    </div>
  `
});
